import React, { useState } from 'react';
import TrackSearch from './components/TrackSearch'; // Import TrackSearch component
import './App.css'; // Import CSS

const App = () => {
  const [searchTerm, setSearchTerm] = useState(''); // State to hold search input
  const [submittedTerm, setSubmittedTerm] = useState(''); // Term to trigger the search in TrackSearch

  // Handle user input in the search bar
  const handleInputChange = (e) => {
    setSearchTerm(e.target.value);
  };

  // Handle search submission
  const handleSearchSubmit = () => {
    setSubmittedTerm(searchTerm); // Pass the search term to TrackSearch for fetching results
  };

  return (
    <div className="app-container">
      <h1 className="title">Welcome to Track Similarity App</h1>
      <p className="description">
        Use this app to search for tracks based on the entered term and listen to previews.
      </p>

      <div className="search-bar">
        <input
          type="text"
          placeholder="Enter track, artist, or album..."
          value={searchTerm}
          onChange={handleInputChange}
          className="text-input wide-text-input"
        />
        <button onClick={handleSearchSubmit} className="search-button">Search</button>
      </div>

      <TrackSearch searchTerm={submittedTerm} /> {/* Pass the search term to TrackSearch */}
    </div>
  );
};

export default App;
